/* Multi-Line Industries Limited - PDF-matched product lookbook.
 * Uses the same product model, colour palette, summary columns, detail fields,
 * four-image gallery and Thank You ending as cart_pdf_service.dart.
 * All coordinates are inches in the 16:9 PowerPoint layout.
 */
async function generateProductPresentation(products, fileName) {
  if (!Array.isArray(products) || products.length === 0) {
    throw new Error('No products found for presentation.');
  }
  if (typeof PptxGenJS === 'undefined') {
    throw new Error('PowerPoint library has not loaded. Check web/index.html.');
  }

  const pptx = new PptxGenJS();
  pptx.layout = 'LAYOUT_WIDE';
  pptx.author = 'Multi-Line Industries Limited';
  pptx.company = 'Multi-Line Industries Limited';
  pptx.subject = 'Premium Product Lookbook';
  pptx.title = 'Display Room | Premium Product Lookbook';
  pptx.lang = 'en-US';
  pptx.theme = { headFontFace: 'Arial', bodyFontFace: 'Arial', lang: 'en-US' };

  const C = {
    ink: '17272C', ink2: '23363B', mint: 'C7EFE7', coral: 'F58270',
    muted: '64747A', line: 'DCE3E3', paper: 'F7F8F7', white: 'FFFFFF',
    green: '208778'
  };
  const SW = 13.333333;
  const SH = 7.5;
  const logoData = 'data:image/png;base64,';
  const T = pptx.ShapeType;

  const str = (value) => {
    if (value === null || value === undefined) return '';
    const text = String(value).trim();
    return text.toLowerCase() === 'null' ? '' : text;
  };
  const value = (s) => str(s) || '-';
  const fmt = (n) => {
    const x = Number(n);
    if (!Number.isFinite(x)) return str(n);
    return Number(x.toFixed(2)).toString();
  };
  const pad = (n) => String(n).padStart(2, '0');
  const date = new Date();
  const dateLabel = `${pad(date.getDate())}.${pad(date.getMonth() + 1)}.${date.getFullYear()}`;
  const titleOf = (p) => str(p.description) || str(p.itemName) || str(p.itemCode) || 'Product';
  const moqOf = (p) => `${fmt(p.moq)} ${str(p.uom)}`.trim();
  const weightOf = (p) => str(p.weightText) || (Number(p.weight) > 0 ? `${fmt(p.weight)} g` : '-');
  const fobOf = (p) => Number(p.fob) > 0 ? fmt(p.fob) : '-';
  const cbmOf = (p) => Number(p.cbm) > 0 ? `${fmt(p.cbm)} CBM` : '-';

  function text(slide, content, x, y, w, h, options = {}) {
    slide.addText(str(content), {
      x, y, w, h, fontFace: 'Arial', fontSize: 12, color: C.ink,
      margin: 0, breakLine: false, valign: 'mid', fit: 'shrink',
      ...options,
    });
  }
  function block(slide, x, y, w, h, bg, radius = 0) {
    slide.addShape(radius ? T.roundRect : T.rect, {
      x, y, w, h, rectRadius: radius || undefined,
      radius: radius || undefined,
      line: { color: bg, transparency: 100 }, fill: { color: bg }
    });
  }
  function outlined(slide, x, y, w, h, color = C.line) {
    slide.addShape(T.roundRect, {
      x, y, w, h, rectRadius: 0.08,
      line: { color, width: 0.9 }, fill: { color: C.white }
    });
  }
  function pill(slide, label, x, y, w, bg = C.mint, fg = C.ink) {
    block(slide, x, y, w, 0.33, bg, 0.14);
    text(slide, label, x + 0.14, y + 0.035, w - 0.28, 0.26,
        { fontSize: 9.5, bold: true, color: fg, align: 'center' });
  }
  function footer(slide, page, extra = '') {
    slide.addShape(T.line, {
      x: 0.63, y: 7.12, w: 12.07, h: 0, line: { color: C.line, width: 0.8 }
    });
    text(slide, 'DISPLAY ROOM / PRODUCT LOOKBOOK', 0.67, 7.17, 5.1, 0.18,
        { fontSize: 8, color: C.muted });
    if (extra) text(slide, extra, 6.2, 7.17, 5.7, 0.18,
        { fontSize: 8, color: C.muted, align: 'right' });
    text(slide, String(page), 12.2, 7.17, 0.46, 0.18,
        { fontSize: 8, bold: true, color: C.green, align: 'right' });
  }
  function drawPhoto(slide, photo, x, y, w, h) {
    if (!photo) {
      block(slide, x, y, w, h, C.paper);
      text(slide, 'Product image not available', x + 0.1, y + h / 2 - 0.18,
          w - 0.2, 0.36, { fontSize: 10, color: C.muted, align: 'center' });
      return;
    }
    // Contain; never stretch product photos out of their original ratio.
    const iw = Number(photo.width) || 1;
    const ih = Number(photo.height) || 1;
    const scale = Math.min(w / iw, h / ih);
    const rw = iw * scale;
    const rh = ih * scale;
    slide.addImage({ data: photo.data, x: x + (w - rw) / 2,
      y: y + (h - rh) / 2, w: rw, h: rh });
  }

  // Convert server image URLs to embedded bytes. Supplying an https path to
  // pptx.addImage in a web browser is not reliable and can leave broken media.
  const imageCache = new Map();
  async function fileAsDataUri(blob) {
    if (typeof FileReader !== 'undefined') {
      return await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result));
        reader.onerror = () => reject(reader.error || Error('Image read failed'));
        reader.readAsDataURL(blob);
      });
    }
    // Node-only for automated smoke tests; browser uses FileReader.
    const bytes = new Uint8Array(await blob.arrayBuffer());
    if (typeof Buffer === 'undefined') throw new Error('No image decoder');
    return `data:${blob.type || 'image/png'};base64,${Buffer.from(bytes).toString('base64')}`;
  }
  function imageDimensionsFromPngData(dataUri) {
    try {
      if (!/^data:image\/png;base64,/i.test(dataUri)) return null;
      const raw = atob(dataUri.split(',')[1].slice(0, 40));
      const n = (at) => ((raw.charCodeAt(at) * 0x1000000) +
        (raw.charCodeAt(at + 1) << 16) + (raw.charCodeAt(at + 2) << 8) +
        raw.charCodeAt(at + 3)) >>> 0;
      return { width: n(16), height: n(20) };
    } catch (_) { return null; }
  }
  async function decodeImage(dataUri) {
    if (typeof Image === 'undefined') {
      // Node smoke tests can use PNG data directly.
      const dimensions = imageDimensionsFromPngData(dataUri);
      return { data: dataUri, ...(dimensions || { width: 1200, height: 900 }) };
    }
    const img = new Image();
    img.src = dataUri;
    if (img.decode) await img.decode();
    else await new Promise((resolve, reject) => {
      img.onload = resolve;
      img.onerror = () => reject(new Error('Could not decode image'));
    });
    const naturalWidth = img.naturalWidth || img.width || 1;
    const naturalHeight = img.naturalHeight || img.height || 1;
    // PowerPoint supports PNG/JPEG. Convert WebP/other browser-decodable
    // formats to JPEG without altering the photo's aspect ratio.
    if (/^data:image\/(png|jpe?g);base64,/i.test(dataUri)) {
      return { data: dataUri, width: naturalWidth, height: naturalHeight };
    }
    const canvas = document.createElement('canvas');
    const scale = Math.min(1, 1600 / Math.max(naturalWidth, naturalHeight));
    canvas.width = Math.max(1, Math.round(naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(naturalHeight * scale));
    const context = canvas.getContext('2d');
    context.fillStyle = '#FFFFFF';
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.drawImage(img, 0, 0, canvas.width, canvas.height);
    return { data: canvas.toDataURL('image/jpeg', 0.88),
      width: naturalWidth, height: naturalHeight };
  }
  async function loadImage(url) {
    const source = str(url);
    if (!source) return null;
    if (!imageCache.has(source)) {
      imageCache.set(source, (async () => {
        try {
          if (source.startsWith('data:image/')) return await decodeImage(source);
          const controller = new AbortController();
          const timeout = setTimeout(() => controller.abort(), 10000);
          try {
            const response = await fetch(source, {
              signal: controller.signal, mode: 'cors', credentials: 'omit'
            });
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            const blob = await response.blob();
            if (!blob.size) throw new Error('Empty image response');
            return await decodeImage(await fileAsDataUri(blob));
          } finally { clearTimeout(timeout); }
        } catch (error) {
          console.warn('PowerPoint image unavailable:', source, error);
          return null;
        }
      })());
    }
    return imageCache.get(source);
  }
  async function photoGallery(product) {
    const urls = [];
    const seen = new Set();
    const push = (raw) => { const url = str(raw); if (url && !seen.has(url)) {
      seen.add(url); urls.push(url); } };
    if (Array.isArray(product.images)) product.images.forEach(push);
    push(product.imageUrl);
    const result = await Promise.all(urls.slice(0, 4).map(loadImage));
    const available = result.filter(Boolean);
    return available.length ? available : [null];
  }

  const galleries = await Promise.all(products.map(photoGallery));
  const logo = await decodeImage(logoData);
  let page = 0;

  // ---- Cover: dark premium PDF palette + original MLIL company logo. ----
  {
    const slide = pptx.addSlide();
    page++;
    slide.background = { color: C.ink };
    block(slide, 11.40, 0, 1.93, SH, C.ink2);
    block(slide, 13.16, 0, 0.17, SH, C.coral);
    text(slide, '', 0.78, 0.59,
      6.1, 0.25, { fontSize: 10, bold: true, color: C.white });
    block(slide, 9.13, 0.44, 3.46, 1.02, C.white, 0.09);
    drawPhoto(slide, logo, 9.35, 0.64, 3.01, 0.63);
    text(slide, 'DISPLAY\nROOM', 0.78, 1.29, 5.4, 2.03,
      { fontSize: 48, bold: true, color: C.white, breakLine: false });
    text(slide, 'Premium Product Lookbook', 0.79, 3.47, 6.2, 0.44,
      { fontSize: 23, bold: true, color: C.mint });
    text(slide, 'A curated catalogue of your selected products, photographs and available specifications.',
      0.80, 4.13, 5.65, 0.72, { fontSize: 12, color: C.white, valign: 'top' });
    pill(slide, `${products.length} PRODUCTS`, 0.80, 5.20, 1.75);
    block(slide, 6.96, 1.91, 5.64, 4.63, C.white, 0.08);
    drawPhoto(slide, galleries[0][0], 7.15, 2.10, 5.27, 4.23);
    text(slide, `GENERATED ${dateLabel}`, 0.79, 7.09, 4, 0.21,
      { fontSize: 10, bold: true, color: C.white });
  }

  // ---- Products at a glance: same 5 columns as PDF, never a QTY column. ----
  const perPage = 10;
  const groupCount = Math.ceil(products.length / perPage);
  for (let group = 0; group < groupCount; group++) {
    const slide = pptx.addSlide();
    page++;
    slide.background = { color: C.white };
    pill(slide, 'CURATED SELECTION', 0.67, 0.46, 2.08);
    text(slide, 'Products at a glance', 0.67, 1.04, 9.6, 0.52,
      { fontSize: 29, bold: true });
    text(slide, 'MOQ = minimum order quantity', 0.68, 1.67, 9.0, 0.24,
      { fontSize: 10.5, color: C.muted });
    const tx = 0.67, ty = 2.06, headH = 0.46, rowH = 0.445;
    const col = [0.52, 5.18, 2.05, 2.42, 1.90];
    const starts = [tx];
    for (let i = 0; i < col.length - 1; i++) starts.push(starts[i] + col[i]);
    block(slide, tx, ty, 12.07, headH, C.ink);
    ['#', 'PRODUCT', 'SUB CATEGORY', 'SIZE', 'MOQ'].forEach((label, i) => {
      text(slide, label, starts[i] + 0.12, ty + 0.055, col[i] - 0.17,
        0.31, { fontSize: i === 2 ? 10 : 10.5, color: C.white, bold: true });
    });
    products.slice(group * perPage, (group + 1) * perPage).forEach((p, idx) => {
      const rowY = ty + headH + idx * rowH;
      if (idx % 2 === 1) block(slide, tx, rowY, 12.07, rowH, C.paper);
      const vals = [String(group * perPage + idx + 1), titleOf(p),
        value(p.subCategory), value(p.sizeRange), `${moqOf(p)}`];
      vals.forEach((v, i) => text(slide, v, starts[i] + 0.12, rowY + 0.045,
        col[i] - 0.20, rowH - 0.09,
        { fontSize: i === 1 ? 9.5 : 10, color: C.ink,
          valign: 'mid', breakLine: false }));
    });
    footer(slide, page, groupCount > 1 ? `GROUP ${group + 1} OF ${groupCount}` : 'GROUP 1');
  }

  function infoCard(slide, label, raw, x, y, w) {
    outlined(slide, x, y, w, 0.61);
    text(slide, label, x + 0.12, y + 0.065, w - 0.24, 0.16,
      { fontSize: 8.0, bold: true, color: C.muted });
    text(slide, value(raw), x + 0.12, y + 0.29, w - 0.24, 0.23,
      { fontSize: 10.5, bold: true, color: C.ink, breakLine: false });
  }
  function highlight(slide, label, raw, x, y, w, bg, fg) {
    block(slide, x, y, w, 0.83, bg, 0.08);
    text(slide, label, x + 0.18, y + 0.13, w - 0.36, 0.17,
      { fontSize: 9.0, bold: true, color: fg });
    text(slide, value(raw), x + 0.18, y + 0.43, w - 0.36, 0.25,
      { fontSize: 15.5, bold: true, color: fg });
  }

  // ---- For each product PDF creates a details page and a gallery page. ----
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    const gallery = galleries[i];
    {
      const slide = pptx.addSlide();
      page++;
      slide.background = { color: C.white };
      block(slide, 0.62, 0.37, 12.08, 0.91, C.ink, 0.08);
      text(slide, `PRODUCT ${pad(i + 1)} / ${pad(products.length)}`, 0.81, 0.48,
        3.5, 0.18, { fontSize: 9.3, bold: true, color: C.mint });
      text(slide, titleOf(p), 0.80, 0.72, 11.7, 0.39,
        { fontSize: 19.5, bold: true, color: C.white });
      outlined(slide, 0.66, 1.57, 5.18, 3.45);
      drawPhoto(slide, gallery[0], 0.83, 1.73, 4.84, 3.13);
      highlight(slide, 'SIZE RANGE', p.sizeRange, 0.66, 5.21, 2.49, C.mint, C.ink);
      highlight(slide, 'MINIMUM ORDER QUANTITY', moqOf(p), 3.34, 5.21, 2.50,
        C.ink, C.white);
      text(slide, 'Full product information', 6.14, 1.46, 6.0, 0.28,
        { fontSize: 12.5, bold: true });
      const fields = [
        ['ITEM CODE', p.itemCode, 'BUSINESS', p.business],
        ['CATEGORY', p.category, 'SUB CATEGORY', p.subCategory],
        ['UOM', p.uom, 'WEIGHT', weightOf(p)],
        ['FOB', fobOf(p), 'CBM', cbmOf(p)],
        ['MATERIAL', p.material, 'SUB INVENTORY', p.subInventory],
        ['ORGANIZATION ID', p.organizationId, 'DISPLAY ROOM', p.displayRoom],
        ['STATUS', p.status, 'BUYER / CLIENT', p.buyer]
      ];
      fields.forEach(([labelA, valueA, labelB, valueB], ri) => {
        const y = 1.82 + ri * 0.675;
        infoCard(slide, labelA, valueA, 6.14, y, 3.07);
        infoCard(slide, labelB, valueB, 9.36, y, 3.32);
      });
      footer(slide, page, `AVAILABLE PHOTOS ${gallery.filter(Boolean).length}`);
    }
    {
      const slide = pptx.addSlide();
      page++;
      slide.background = { color: C.white };
      pill(slide, `PRODUCT ${i + 1} / IMAGE GALLERY`, 0.66, 0.47, 3.10);
      text(slide, titleOf(p), 0.66, 1.06, 12.0, 0.54,
        { fontSize: 29, bold: true });
      text(slide, 'Additional product photographs supplied by the server.',
        0.67, 1.68, 11.9, 0.22, { fontSize: 10.5, color: C.muted });
      const displayed = gallery.slice(0, 4);
      const compact = displayed.length > 2;
      const boxH = compact ? 1.78 : 3.90;
      displayed.forEach((photo, k) => {
        const col = k % 2;
        const row = Math.floor(k / 2);
        const x = col ? 6.76 : 0.67;
        const y = (compact ? 2.02 + row * 2.36 : 2.04);
        outlined(slide, x, y, 5.91, boxH);
        drawPhoto(slide, photo, x + 0.15, y + 0.12,
          5.61, boxH - 0.24);
        text(slide, `VIEW ${k + 1}`, x, y + boxH + 0.06, 5.91, 0.20,
          { fontSize: 10, bold: true, color: C.green, align: 'center' });
      });
      footer(slide, page);
    }
  }

  // ---- Same minimalist final page as PDF. No logo, footer or extra words. ----
  {
    const slide = pptx.addSlide();
    slide.background = { color: C.ink };
    text(slide, 'Thank You', 1.4, 3.03, 10.53, 1.05,
      { fontSize: 53, color: C.white, bold: true, align: 'center' });
  }

  await pptx.writeFile({ fileName, compression: true });
  return true;
}

// Used by presentation_bridge_web.dart; keep the existing public JS API.
window.generateProductPresentation = generateProductPresentation;
